function identityPools(){return{headwear:HEADWEAR_ITEMS,face:FACE_ITEMS,top:TOP_ITEMS,bottom:BOTTOM_ITEMS,accessory:ACCESSORY_ITEMS,profilebg:PROFILE_BACKGROUNDS,entry:ENTRY_ANIMATIONS,victory:VICTORY_ANIMATIONS,defeat:DEFEAT_ANIMATIONS,response:RESPONSE_EFFECTS,emote:EMOTES_COLLECTION,spray:SPRAYS_COLLECTION}}
function identityConfig(type){return{headwear:{ownedKey:"ownedHeadwear",equipKey:"headwear"},face:{ownedKey:"ownedFaceItems",equipKey:"faceItem"},top:{ownedKey:"ownedTopItems",equipKey:"topItem"},bottom:{ownedKey:"ownedBottomItems",equipKey:"bottomItem"},accessory:{ownedKey:"ownedAccessoryItems",equipKey:"accessoryItem"},profilebg:{ownedKey:"ownedProfileBackgrounds",equipKey:"profileBackground"},entry:{ownedKey:"ownedEntryAnimations",equipKey:"entryAnimation"},victory:{ownedKey:"ownedVictoryAnimations",equipKey:"victoryAnimation"},defeat:{ownedKey:"ownedDefeatAnimations",equipKey:"defeatAnimation"},response:{ownedKey:"ownedResponseEffects",equipKey:"responseEffect"},emote:{ownedKey:"ownedEmotes",equipKey:null},spray:{ownedKey:"ownedSprays",equipKey:null}}[type]}
function findIdentityItem(type,id){return(identityPools()[type]||[]).find(x=>x.id===id)}
function identityOwns(type,id,target=save){const i=ensureIdentityState(target),cfg=identityConfig(type);return !!cfg&&i[cfg.ownedKey]?.includes(id)}
function identityUnlock(type,id,target=save){const i=ensureIdentityState(target),cfg=identityConfig(type);if(!cfg)return;const arr=i[cfg.ownedKey]=uniqueStrings(i[cfg.ownedKey]||[],[]);if(!arr.includes(id))arr.push(id)}
function identityEquip(type,id){const i=ensureIdentityState();const cfg=identityConfig(type);if(!cfg||!identityOwns(type,id))return;if(cfg.equipKey){i[cfg.equipKey]=id;if(["headwear","face","top","bottom","accessory"].includes(type)){i.baseAvatar="custom";save.avatar="custom"}persist();renderAvatarBuilder();renderSideAvatar();renderIdentity();renderCollectionCatalogSummary();toast(`✅ ${findIdentityItem(type,id)?.name||id} equipado`)}}
function identityCostLabel(item){if(item.currency==="gems")return `${item.cost} 💎`;if(item.currency==="coins")return `${item.cost} 🪙`;if(item.currency==="unlock")return `🔒 Set / Prestigio`;return item.cost?`${item.cost} 🪙`:`Gratis`}
function buyIdentityItem(type,id){ensureEconomyState();const item=findIdentityItem(type,id);if(!item)return; if(identityOwns(type,id)){if(type==="emote")return toggleIdentityEmote(id);if(type==="spray")return toggleIdentitySpray(id);return identityEquip(type,id);} if(item.currency==="unlock")return toast("🔒 Este cosmético se consigue por set, evento o prestigio"); if(item.currency==="gems"){if(save.gems<item.cost)return toast("No tienes suficientes diamantes");save.gems-=item.cost;save.economyStats.gemsSpent+=item.cost}else{if(save.coins<item.cost)return toast("No tienes suficientes monedas");save.coins-=item.cost;save.economyStats.coinsSpent+=item.cost} identityUnlock(type,id); if(type==="emote")toggleIdentityEmote(id);else if(type==="spray")toggleIdentitySpray(id);else identityEquip(type,id); beep("coin")}
function identityEmoteEquipped(id){const i=ensureIdentityState();return i.equippedEmotes.includes(id)}
function equipIdentityEmote(id){const i=ensureIdentityState();if(!identityOwns("emote",id))return;if(!i.equippedEmotes.includes(id)){if(i.equippedEmotes.length>=6)return toast("Máximo 6 emotes equipados");i.equippedEmotes.push(id)}i.primaryEmote=id;persist();renderAvatarBuilder();renderGameAvatarWidget("ready");renderMpReactionToolbar();toast(`😄 ${EMOTES_COLLECTION.find(x=>x.id===id)?.name||id} visible en tu avatar`)}
function removeIdentityEmote(id){const i=ensureIdentityState();i.equippedEmotes=i.equippedEmotes.filter(x=>x!==id);if(i.primaryEmote===id)i.primaryEmote=i.equippedEmotes[0]||"";persist();renderAvatarBuilder();renderGameAvatarWidget("ready");renderMpReactionToolbar()}
function toggleIdentityEmote(id){const i=ensureIdentityState();if(i.equippedEmotes.includes(id)&&i.primaryEmote===id)return removeIdentityEmote(id);return equipIdentityEmote(id)}
function identitySprayEquipped(id){return ensureIdentityState().equippedSprays.includes(id)}
function toggleIdentitySpray(id){const i=ensureIdentityState();if(!identityOwns("spray",id))return;if(i.equippedSprays.includes(id))i.equippedSprays=i.equippedSprays.filter(x=>x!==id);else{if(i.equippedSprays.length>=3)return toast("Máximo 3 sprays equipados");i.equippedSprays.push(id)}persist();renderAvatarBuilder();renderMpReactionToolbar()}
function buyIdentitySpray(id){ensureEconomyState();const item=findIdentityItem("spray",id);if(!item)return;if(identityOwns("spray",id))return toggleIdentitySpray(id);if(item.currency==="unlock")return toast("🏆 Este spray es de Prestigio");if(item.currency==="gems"){if(save.gems<item.cost)return toast("No tienes suficientes diamantes");save.gems-=item.cost;save.economyStats.gemsSpent+=item.cost}else{if(save.coins<item.cost)return toast("No tienes suficientes monedas");save.coins-=item.cost;save.economyStats.coinsSpent+=item.cost}identityUnlock("spray",id);toggleIdentitySpray(id);beep("coin")}
