function identityThemeOwned(theme){const all=identityThemePool(theme);let owned=0;all.forEach(item=>{const type=(HEADWEAR_ITEMS.includes(item)?"headwear":FACE_ITEMS.includes(item)?"face":TOP_ITEMS.includes(item)?"top":BOTTOM_ITEMS.includes(item)?"bottom":ACCESSORY_ITEMS.includes(item)?"accessory":PROFILE_BACKGROUNDS.includes(item)?"profilebg":ENTRY_ANIMATIONS.includes(item)?"entry":VICTORY_ANIMATIONS.includes(item)?"victory":DEFEAT_ANIMATIONS.includes(item)?"defeat":RESPONSE_EFFECTS.includes(item)?"response":EMOTES_COLLECTION.includes(item)?"emote":"spray");if(identityOwns(type,item.id))owned++});return owned}
function ownsBySpec(spec,target=save){if(spec.type==="avatar")return (target.avatars||[]).includes(spec.id)||["starter_m","starter_f","brain","custom"].includes(spec.id);if(spec.type==="frame")return (target.framesOwned||[]).includes(spec.id);if(spec.type==="aura")return (target.aurasOwned||[]).includes(spec.id);return identityOwns(spec.type,spec.id,target)}
