let storageOK=true;
function load(){try{
 const r=window.localStorage.getItem("triviaArenaPocketSave");if(!r)return blank();
 const o=JSON.parse(r),b=blank();
 let migratedCustom={...b.customAvatar};
 if(o.customAvatar&&o.customAvatar.skin)migratedCustom={...migratedCustom,...o.customAvatar};
 else if(o.customAvatar)migratedCustom.bg=o.customAvatar.bg||"violet";
 if(!o.customAvatar?.presentation)migratedCustom.presentation=(o.profileGender==="female"?"female":"male");
 const s={...b,...o,
  settings:{...b.settings,...(o.settings||{})},
  inv:{...b.inv,...(o.inv||{})},
  customAvatar:migratedCustom,
  catStats:{...b.catStats,...(o.catStats||{})},
  questionHistory:{...(o.questionHistory||{})},
  procHistory:{...(o.procHistory||{})},
  conceptHistory:{...(o.conceptHistory||{})},
  formatHistory:{...(o.formatHistory||{})},
  generalDecks:{...(o.generalDecks||{})},
  framesOwned:[...new Set(["none",...(o.framesOwned||["none"])])],
  selectedFrame:o.selectedFrame||"none",
  bossBest:o.bossBest??Math.min((o.bosses||[]).length,10),
  bossClears:o.bossClears||0,
  avatars:[...new Set(["starter_m","starter_f","brain",...(o.avatars||b.avatars)])],
  profileGender:o.profileGender||b.profileGender,
  profileBio:o.profileBio||"",
  featuredAchievement:o.featuredAchievement||"",
  wardrobeOwned:[...new Set(["hoodie",...(o.wardrobeOwned||["hoodie"])])],
  equippedOutfit:o.equippedOutfit||"hoodie",
  outfitXp:{hoodie:0,...(o.outfitXp||{})},
  aurasOwned:[...new Set(["none",...(o.aurasOwned||["none"])])],
  selectedAura:o.selectedAura||"none",
  totalXp:Number(o.totalXp||0),
  creatorUnlockAll:!!o.creatorUnlockAll,
  season:{...b.season,...(o.season||{})},
  missionState:{...b.missionState,...(o.missionState||{})},
  loginStreak:{...b.loginStreak,...(o.loginStreak||{})},
  chestStats:{...b.chestStats,...(o.chestStats||{})},
  keyring:{...b.keyring,...(o.keyring||{}),silver:Number(o.keyring?.silver??o.keys??b.keyring.silver)},
  chestInventory:{...b.chestInventory,...(o.chestInventory||{})},fragments:{...(o.fragments||{})},vault:{...b.vault,...(o.vault||{}),claimed:[...new Set(o.vault?.claimed||[])]},album:{...b.album,...(o.album||{}),claimed:[...new Set(o.album?.claimed||[])]},economyStats:{...b.economyStats,...(o.economyStats||{})},selectedTitle:o.selectedTitle||"",profileAnimation:o.profileAnimation||"none",animationsOwned:[...new Set(["none",...(o.animationsOwned||[])])],
  lifetime:{...b.lifetime,...(o.lifetime||{})},
  worldTour:{...b.worldTour,...(o.worldTour||{}),countries:{...(o.worldTour?.countries||{})},continentsClaimed:[...new Set(o.worldTour?.continentsClaimed||[])],passportClaimed:[...new Set(o.worldTour?.passportClaimed||[])],questionDecks:{...(o.worldTour?.questionDecks||{})}}
 };
 if(s.creatorUnlockAll){
  s.avatars=[...new Set([...s.avatars,...AVATARS.map(a=>a.id),"custom"])];
  s.framesOwned=[...new Set([...s.framesOwned,...FRAMES.map(f=>f.id)])];
  s.effectsOwned=[...new Set([...s.effectsOwned,...VISUAL_FX.map(f=>f.id)])];
  s.wardrobeOwned=[...new Set([...s.wardrobeOwned,...OUTFITS.map(x=>x.id)])];
  s.aurasOwned=[...new Set([...s.aurasOwned,...AVATAR_AURAS.map(x=>x.id)])]
 }
 s.level=Math.max(1,Math.min(MAX_LEVEL,Number(s.level||1)));
 s.xp=Math.max(0,Number(s.xp||0));
 if(!s.wardrobeOwned.includes(s.equippedOutfit))s.equippedOutfit=s.wardrobeOwned[0]||"hoodie";
 if(!s.aurasOwned.includes(s.selectedAura))s.selectedAura=s.aurasOwned[0]||"none";s.keyring.silver=Math.max(0,Number(s.keyring.silver||0));s.keyring.gold=Math.max(0,Number(s.keyring.gold||0));s.keyring.diamond=Math.max(0,Number(s.keyring.diamond||0));s.keys=s.keyring.silver;
 Object.keys(CATS).forEach(c=>{if(!s.catStats[c])s.catStats[c]={correct:0,total:0}});
 return s
}catch(e){storageOK=false;return blank()}}
let save=load(),state=null,audio=null,musicTimer=null,musicStep=0,musicStarted=false,questionTimer=null,questionDeadline=0;
const $=id=>document.getElementById(id);
function persist(){try{if(storageOK)window.localStorage.setItem("triviaArenaPocketSave",JSON.stringify(save))}catch(e){storageOK=false}refresh();scheduleOnlineProfileSync()}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function scrambleQuestion(q){const pairs=q.a.map((text,i)=>({text,correct:i===q.ok}));const mixed=shuffle(pairs);return{...q,a:mixed.map(x=>x.text),ok:mixed.findIndex(x=>x.correct)}}
function chooseQuestions(pool,count,key){
 const wanted=Math.min(count,pool.length);let hist=[...(save.questionHistory[key]||[])];
 let available=pool.filter(q=>!hist.includes(q.id));
 if(available.length<wanted){hist=hist.slice(-Math.max(0,Math.floor(pool.length*.25)));available=pool.filter(q=>!hist.includes(q.id))}
 let picked=shuffle(available).slice(0,wanted);
 if(picked.length<wanted){const used=new Set(picked.map(q=>q.id));picked=picked.concat(shuffle(pool.filter(q=>!used.has(q.id))).slice(0,wanted-picked.length))}
 save.questionHistory[key]=[...hist,...picked.map(q=>q.id)].slice(-Math.max(wanted*2,Math.floor(pool.length*.75)));
 return picked.map(scrambleQuestion)
}
